// Quote every value, and neutralize spreadsheet formulas in user-entered cells.
export function csvCell(value) {
  const text = String(value ?? '')
  const safe =
    /^[\s\p{Cc}]*[=+@-]/u.test(text) || ['\t', '\r', '\n'].includes(text[0])
      ? `'${text}`
      : text
  return `"${safe.replace(/"/g, '""')}"`
}

export function casesToCsv(cases, statuses) {
  const rows = [
    [
      'Case Number',
      'Borrower Name',
      'Created By',
      'Quote Generated By',
      'Loan Amount (INR)',
      'Status',
    ],
  ]
  for (const item of cases) {
    rows.push([
      item.caseNumber,
      item.borrowerName,
      item.caseCreatedBy,
      item.quoteGeneratedBy,
      item.loanAmount,
      statuses.find((status) => status.id === item.status)?.label ||
        item.status,
    ])
  }
  return '\uFEFF' + rows.map((row) => row.map(csvCell).join(',')).join('\r\n')
}

export function downloadCases(cases, statuses) {
  const blob = new Blob([casesToCsv(cases, statuses)], {
    type: 'text/csv;charset=utf-8',
  })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = 'orenda-cases.csv'
  document.body.append(link)
  link.click()
  link.remove()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}
